import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import styles from './LoginPage.module.css';

const LoginPage = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSignIn = (e) => {
    e.preventDefault();
    setError('');

    if (!email || !password) {
      setError('Please fill in all fields');
      return;
    }

    setLoading(true);

    // Simulate API call
    setTimeout(() => {
      setLoading(false);
      // Store user info in localStorage
      localStorage.setItem('user', JSON.stringify({ email, name: email.split('@')[0] }));
      navigate('/account');
    }, 500);
  };

  return (
    <div className={styles.container}>
      {/* Hero Section - Left */}
      <div className={styles.heroSection}>
        <img
          src="https://images.unsplash.com/photo-1599643478518-a784e5dc4c8f?w=800&q=80"
          alt="Luxury Jewelry"
          className={styles.heroImage}
        />
        <div className={styles.heroOverlay}>
          <h2 className={styles.heroTitle}>Timeless Craftsmanship</h2>
          <p className={styles.heroSubtitle}>Discover luxury jewelry that tells your story</p>
        </div>
      </div>

      {/* Form Section - Right */}
      <div className={styles.formSection}>
        <div className={styles.formContainer}>
          <h1 className={styles.title}>Welcome Back</h1>
          <p className={styles.subtitle}>Sign in to your account to continue shopping</p>

          <form onSubmit={handleSignIn} className={styles.form}>
            {error && <div className={styles.error}>{error}</div>}

            <div className={styles.formGroup}>
              <label htmlFor="email" className={styles.label}>
                EMAIL ADDRESS
              </label>
              <input
                type="email"
                id="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className={styles.input}
                placeholder="you@example.com"
              />
            </div>

            <div className={styles.formGroup}>
              <label htmlFor="password" className={styles.label}>
                PASSWORD
              </label>
              <input
                type="password"
                id="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className={styles.input}
                placeholder="••••••••"
              />
            </div>

            <button type="submit" className={styles.button} disabled={loading}>
              {loading ? 'Signing In...' : 'SIGN IN'}
            </button>
          </form>

          <div className={styles.divider}></div>

          <div className={styles.footer}>
            <a href="#forgot" className={styles.link}>
              Forgot Password?
            </a>
            <span className={styles.separator}>•</span>
            <button
              onClick={() => navigate('/register')}
              className={styles.linkButton}
            >
              Create Account
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
